_seals=count()

def seal(label='BELLEZA CON RAÍCES · AURA · EL SAUZAL · '):
 ident=f'seal-path-{next(_seals)}'
 return f'''<div class="aura-seal" aria-hidden="true"><svg viewBox="0 0 180 180"><defs><path id="{ident}" d="M90,90 m-66,0 a66,66 0 1,1 132,0 a66,66 0 1,1 -132,0"/></defs><circle cx="90" cy="90" r="83"/><circle cx="90" cy="90" r="52"/><text><textPath href="#{ident}" textLength="410">{label}</textPath></text><path class="seal-petal" d="M90 125C52 103 62 73 90 48c28 25 38 55 0 77Zm0 0C37 113 42 76 49 64c32 10 47 35 41 61Zm0 0c53-12 48-49 41-61-32 10-47 35-41 61Z"/></svg></div>'''

